<?php
declare(strict_types=1);
namespace CommunityHub;
final class IntegrationAdmin {
 public static function serverInput(array $d,bool $create):array{$v=[];foreach(['name'=>120,'hostname'=>255,'connect_url'=>255,'restart_schedule'=>255] as $k=>$max)$v[$k]=App::text($d[$k]??'',$k,$max,$k!=='name')?:null;$v['framework']=$d['framework']??'standalone';$v['max_players']=filter_var($d['max_players']??64,FILTER_VALIDATE_INT);$v['is_enabled']=(int)!empty($d['is_enabled']);if(!in_array($v['framework'],['standalone','qbcore'],true)||$v['max_players']===false||$v['max_players']<1||$v['max_players']>2048)throw new HttpError('Select a supported framework and a player limit between 1 and 2048.');if($v['connect_url']&&!preg_match('~^(fivem://connect/|https://cfx\.re/join/)[^\s]+$~i',$v['connect_url']))throw new HttpError('Use a FiveM connect URL or an https://cfx.re/join/ link.');if($create){$v['server_key']=App::text($d['server_key']??null,'Server key',80);if(!preg_match('/^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$/',$v['server_key']))throw new HttpError('Use letters, numbers, underscores or hyphens for the server key.');}return $v;}
 public static function handle(array $u,string $method,string $path,array $d):void{Domain::role($u,Domain::ADMINS);if($method==='POST'){
  if($path==='/admin/fivem/servers'){$v=self::serverInput($d,true);App::query('INSERT INTO fivem_servers(name,hostname,connect_url,restart_schedule,framework,max_players,is_enabled,server_key) VALUES(?,?,?,?,?,?,?,?)',array_values($v));App::redirect('/admin/fivem');}
  if(preg_match('~^/admin/fivem/servers/(\d+)$~',$path,$m)){$v=self::serverInput($d,false);App::query('UPDATE fivem_servers SET name=?,hostname=?,connect_url=?,restart_schedule=?,framework=?,max_players=?,is_enabled=? WHERE id=?',[...array_values($v),(int)$m[1]]);App::redirect('/admin/fivem');}
  if($path==='/admin/fivem/api-keys'){$name=App::text($d['name']??null,'Key name',120);$server=!empty($d['server_id'])?App::id($d['server_id']):null;if($server&&!App::row('SELECT id FROM fivem_servers WHERE id=?',[$server]))throw new HttpError('Server not found.',404);$raw='ch_fivem_'.bin2hex(random_bytes(32));App::query('INSERT INTO fivem_api_keys(name,server_id,key_hash,key_prefix,created_by) VALUES(?,?,?,?,?)',[$name,$server,hash('sha256',$raw),substr($raw,0,16),$u['id']]);$_SESSION['new_api_key']=$raw;App::redirect('/admin/fivem');}
  if(preg_match('~^/admin/fivem/api-keys/(\d+)/revoke$~',$path,$m)){App::query('UPDATE fivem_api_keys SET is_active=0 WHERE id=?',[(int)$m[1]]);App::redirect('/admin/fivem');}
  if($path==='/admin/fivem/announcements'){$priority=in_array($d['priority']??'',['info','important','critical'],true)?$d['priority']:'info';App::query('INSERT INTO fivem_announcements(title,message,priority,is_active,expires_at,created_by) VALUES(?,?,?,?,?,?)',[App::text($d['title']??null,'Title',180),App::text($d['message']??null,'Message',10000),$priority,(int)!empty($d['is_active']),$d['expires_at']?:null,$u['id']]);App::redirect('/admin/fivem');}
  throw new HttpError('FiveM administration action not found.',404);
 }$servers=App::rows('SELECT *,IF(last_heartbeat_at>DATE_SUB(NOW(),INTERVAL 90 SECOND),1,0) live FROM fivem_servers ORDER BY id');if($path==='/admin/fivem/live')App::json(['ok'=>true,'servers'=>$servers,'updatedAt'=>date(DATE_ATOM)]);if($path!=='/admin/fivem')throw new HttpError('Page not found.',404);View::layout('FiveM configuration',function()use($servers){View::heading('FiveM configuration','Manage servers, API keys and tablet bulletins.');if(isset($_SESSION['new_api_key'])){?><section class="panel api-secret"><h2>Your new API key</h2><p>Copy this key into the server-only resource configuration. It is displayed once.</p><pre><?=escape($_SESSION['new_api_key'])?></pre></section><?php unset($_SESSION['new_api_key']);}$fields=['name'=>['label'=>'Server name','required'=>true],'hostname'=>'Hostname','connect_url'=>'FiveM connect URL','restart_schedule'=>'Restart schedule','framework'=>['label'=>'Framework','options'=>['standalone'=>'Standalone / vMenu','qbcore'=>'QBCore']],'max_players'=>['label'=>'Maximum players','type'=>'number','default'=>64],'is_enabled'=>['label'=>'Enabled','type'=>'checkbox','default'=>true]];foreach($servers as $s){?><section class="panel server-card"><h2><?=escape($s['name'])?></h2><p>Server key: <code><?=escape($s['server_key'])?></code> · <?=$s['live']?'Online':'Offline'?></p><?php View::form('/admin/fivem/servers/'.$s['id'],$fields,'Save server',$s);?></section><?php }?><section class="panel"><h2>Add server</h2><?php View::form('/admin/fivem/servers',['server_key'=>['label'=>'Unique server key','required'=>true],...$fields],'Add server');?></section><section class="panel"><h2>API keys</h2><?php View::table(App::rows('SELECT k.id,k.name,k.key_prefix,k.is_active,k.last_used_at,s.name server_name FROM fivem_api_keys k LEFT JOIN fivem_servers s ON s.id=k.server_id ORDER BY k.id DESC'),['name'=>'Name','key_prefix'=>'Prefix','server_name'=>'Server','is_active'=>'Active','last_used_at'=>'Last used'],fn($k)=>View::form('/admin/fivem/api-keys/'.$k['id'].'/revoke',[],'Revoke'));View::form('/admin/fivem/api-keys',['name'=>['label'=>'Key name','required'=>true],'server_id'=>['label'=>'Assigned server','options'=>[''=>'All servers']+array_column($servers,'name','id')]],'Generate API key');?></section><section class="panel"><h2>Tablet bulletins</h2><?php View::form('/admin/fivem/announcements',['title'=>['label'=>'Title','required'=>true],'message'=>['label'=>'Message','type'=>'textarea','required'=>true],'priority'=>['label'=>'Priority','options'=>['info'=>'Info','important'=>'Important','critical'=>'Critical']],'is_active'=>['label'=>'Active','type'=>'checkbox','default'=>true],'expires_at'=>['label'=>'Expires','type'=>'datetime-local']],'Publish bulletin');?></section><section class="panel"><h2>Resource setup</h2><pre>Config.ApiBase = "<?=escape(App::base('/api/fivem'))?>"</pre><p>Keep API keys in server-side <code>config.lua</code>. Match the key's assigned server to <code>Config.ServerKey</code>. Postal settings belong in <code>client/config.lua</code>.</p></section><?php });}
}
